#include "mesh.hpp"
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <sys/wait.h>
#include <fcntl.h>
#include <unistd.h>
namespace fs=std::filesystem;
Json read(const fs::path&p){std::ifstream f(p);if(!f)throw std::runtime_error(p.string());Json j;f>>j;return j;}
void save(const fs::path&p,const Json&j){fs::create_directories(p.parent_path());std::ofstream(p)<<j.dump(2)<<'\n';}
void run(const fs::path&exe,const std::vector<std::string>&args,const fs::path&log){pid_t pid=fork();if(pid==0){int fd=open(log.c_str(),O_CREAT|O_WRONLY|O_TRUNC,0644);dup2(fd,1);dup2(fd,2);close(fd);std::vector<char*>v;std::string bin=exe.string();v.push_back(bin.data());for(auto&a:args)v.push_back(const_cast<char*>(a.c_str()));v.push_back(nullptr);execv(bin.c_str(),v.data());_exit(127);}if(pid<0)throw std::runtime_error("fork");int s;waitpid(pid,&s,0);if(!WIFEXITED(s)||WEXITSTATUS(s))throw std::runtime_error("child failed: "+log.string());}
int main(int argc,char**argv){try{if(argc!=5)throw std::runtime_error("run INPUTS BIN PARAMS OUTPUT");fs::path inputs=fs::absolute(argv[1]),bin=fs::absolute(argv[2]),params=fs::absolute(argv[3]),out=fs::absolute(argv[4]);if(fs::exists(out/"SUMMARY.json"))throw std::runtime_error("Refusing overwrite");fs::create_directories(out);auto protocol=read(inputs/"PROTOCOL.json");Json rows=Json::array();for(const auto&lv:protocol.at("levels")){std::string level=lv;auto scene_path=inputs/"assets"/level/"scene.json";auto scene=read(scene_path);for(std::string mode:{"free","center"}){auto folder=out/level/mode;fs::create_directories(folder);save(out/"STATUS.json",{{"state","running"},{"level",level},{"mode",mode},{"completed",rows.size()},{"pid",getpid()}});run(bin/"dynamic_togt_planner",{scene_path.string(),folder.string(),mode,params.string(),(inputs/"vehicle.json").string()},folder/"process.log");auto result=read(folder/"result.json");Json assessment=nullptr;std::string verdict="未找到";if(result.at("found").get<bool>()){assessment=mesh_evaluate(Trajectory::load(result),scene);save(folder/"assessment.json",assessment);verdict=assessment.at("collision_detected").get<bool>()?"碰撞":assessment.at("passed").get<bool>()?"通过":(!assessment.at("ordered_exactly_once").get<bool>()||!assessment.at("endpoints_passed").get<bool>())?"未完成":"证据不足";}rows.push_back({{"level",level},{"mode",mode},{"verdict",verdict},{"trajectory_s",result.at("nominal_time_s")},{"compute_s",result.at("total_compute_s")},{"iterations",result.at("iterations")},{"optimizer_message",result.at("optimizer_message")},{"result",(folder/"result.json").string()}});save(out/"SUMMARY.json",rows);std::ofstream report(out/"PLANNING.md");report<<"# 动态 TOGT 作者源码复核：22 条件\n\n独立单初值；原 L-BFGS、原权重 1、16 积分区间。规划球 0.20 m，实体碰撞球 0.15 m；沿用冻结赛道和终点。仅规划。通过表示数值几何、门序与终点检查通过，不代表严格区间证书或实飞。\n\n|条件|方法|结论|轨迹时间/s|求解墙钟/s|迭代|\n|---|---|---|---:|---:|---:|\n";report<<std::fixed<<std::setprecision(6);for(auto&r:rows)report<<"|"<<r["level"].get<std::string>()<<"|"<<r["mode"].get<std::string>()<<"|"<<r["verdict"].get<std::string>()<<"|"<<r["trajectory_s"].get<double>()<<"|"<<r["compute_s"].get<double>()<<"|"<<r["iterations"]<<"|\n";std::cout<<level<<" "<<mode<<" "<<verdict<<" "<<result["nominal_time_s"]<<std::endl;}}
save(out/"STATUS.json",{{"state","complete"},{"completed",rows.size()},{"pid",getpid()}});return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
